int main() {
    int M, N;
    int first = 1;
    while (scanf("%d %d", &M, &N) == 2 && (M || N)) {
        int rows = M + 1, cols = N + 1;
        long long table[20][20];
        int isQ[20][20];

        for (int i = 0; i < rows; i++)
            for (int j = 0; j < cols; j++) {
                char buf[50];
                scanf("%s", buf);
                if (buf[0] == '?') { isQ[i][j] = 1; table[i][j] = 0; }
                else { isQ[i][j] = 0; table[i][j] = atoll(buf); }
            }

        int changed = 1;
        while (changed) {
            changed = 0;
            for (int i = 0; i < rows; i++) {
                int qcount = 0, qj = -1; long long sum = 0;
                for (int j = 0; j < cols; j++) {
                    if (isQ[i][j]) { qcount++; qj = j; }
                    else sum += table[i][j];
                }
                if (qcount == 1) {
                    // last col is total for row i
                    // sum of first N cols = table[i][cols-1]
                    // Actually: sum of all = 0 constraint isn't right
                    // Row sum: sum of cols 0..N-1 = table[i][N]
                    // But last col might be the '?'
                    long long rowsum = 0;
                    for (int j = 0; j < cols-1; j++) if (!isQ[i][j]) rowsum += table[i][j];
                    // table[i][cols-1] = rowsum + (qj < cols-1 ? 0 : 0)
                    // The constraint: sum of first N = last col
                    // total sum of all cols including last = 2*last? No.
                    // Let me redo: row total is last element
                    // sum[j=0..N-1] table[i][j] = table[i][N]
                    // All N+1 values with one unknown
                    long long s = 0;
                    for (int j = 0; j < cols; j++) if (!isQ[i][j]) s += (j < cols-1 ? 1 : -1) * table[i][j];
                    // s + val*(j<cols-1 ? 1 : -1) = 0
                    if (qj < cols-1) table[i][qj] = -s; // val = -s
                    else table[i][qj] = s; // -val = -s => val = s... wait
                    // sum of data = total: sum_{j<N} t[i][j] - t[i][N] = 0
                    // s + unknown * sign = 0
                    table[i][qj] = (qj < cols-1) ? -s : s;
                    isQ[i][qj] = 0; changed = 1;
                }
            }
            for (int j = 0; j < cols; j++) {
                int qcount = 0, qi = -1; long long s = 0;
                for (int i = 0; i < rows; i++) {
                    if (isQ[i][j]) { qcount++; qi = i; }
                    else s += (i < rows-1 ? 1 : -1) * table[i][j];
                }
                if (qcount == 1) {
                    table[qi][j] = (qi < rows-1) ? -s : s;
                    isQ[qi][j] = 0; changed = 1;
                }
            }
        }

        int hasQ = 0;
        for (int i = 0; i < rows; i++) for (int j = 0; j < cols; j++) if (isQ[i][j]) hasQ = 1;

        // Verify
        int ok = 1;
        if (!hasQ) {
            for (int i = 0; i < rows-1; i++) { long long s=0; for(int j=0;j<cols-1;j++) s+=table[i][j]; if(s!=table[i][cols-1]) ok=0; }
            for (int j = 0; j < cols-1; j++) { long long s=0; for(int i=0;i<rows-1;i++) s+=table[i][j]; if(s!=table[rows-1][j]) ok=0; }
        }

        if (!first) printf("\n");
        first = 0;

        if (hasQ || !ok) printf("NO\n");
        else {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (j) printf(" ");
                    printf("%lld", table[i][j]);
                }
                printf("\n");
            }
        }
    }
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAXN 35
#define MAXTOK 64
#define EPS 1e-9

typedef struct {
    int type;   /* 0 = known, 1 = unknown */
    double val; /* known value */
} Cell;

static int is_number(const char *s) {
    if (s[0] == '\0') return 0;
    int i = 0;
    if (s[i] == '-' || s[i] == '+') i++;
    if (!isdigit((unsigned char)s[i])) return 0;
    long long v = 0;
    while (s[i]) {
        if (!isdigit((unsigned char)s[i])) return 0;
        v = v * 10 + (s[i] - '0');
        i++;
    }
    (void)v;
    return 1;
}

int main(void) {
    int firstCase = 1;

    while (1) {
        int r, c;
        if (scanf("%d %d", &r, &c) != 2) return 0;
        if (r == 0 && c == 0) break;

        /* Table size includes row totals and column totals:
           input gives original data size r x c, so actual table is (r+1) x (c+1). */
        int R = r + 1, C = c + 1;

        Cell a[MAXN][MAXN];
        int unknownId[MAXN][MAXN];
        memset(unknownId, -1, sizeof(unknownId));

        int varCnt = 0;
        char tok[MAXTOK];

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                scanf("%s", tok);
                if (strcmp(tok, "?") == 0) {
                    a[i][j].type = 1;
                    a[i][j].val = 0;
                    unknownId[i][j] = varCnt++;
                } else {
                    a[i][j].type = 0;
                    a[i][j].val = atof(tok);
                }
            }
        }

        /* Build linear equations:
           For each non-total row i < r: sum j=0..c-1 cell(i,j) - cell(i,c) = 0
           For each non-total col j < c: sum i=0..r-1 cell(i,j) - cell(r,j) = 0
           Last total-total cell equation is redundant, not needed. */
        int eqCnt = r + c;
        double mat[70][70]; /* enough for <= 30+30 vars/eqs in typical constraints */
        memset(mat, 0, sizeof(mat));

        int eq = 0;
        for (int i = 0; i < r; i++, eq++) {
            double rhs = 0.0;
            for (int j = 0; j < c; j++) {
                if (a[i][j].type) mat[eq][unknownId[i][j]] += 1.0;
                else rhs -= a[i][j].val;
            }
            if (a[i][c].type) mat[eq][unknownId[i][c]] += -1.0;
            else rhs += a[i][c].val;
            mat[eq][varCnt] = rhs;
        }
        for (int j = 0; j < c; j++, eq++) {
            double rhs = 0.0;
            for (int i = 0; i < r; i++) {
                if (a[i][j].type) mat[eq][unknownId[i][j]] += 1.0;
                else rhs -= a[i][j].val;
            }
            if (a[r][j].type) mat[eq][unknownId[r][j]] += -1.0;
            else rhs += a[r][j].val;
            mat[eq][varCnt] = rhs;
        }

        /* Gaussian elimination for augmented matrix eqCnt x (varCnt+1) */
        int where[70];
        for (int i = 0; i < varCnt; i++) where[i] = -1;

        int row = 0;
        for (int col = 0; col < varCnt && row < eqCnt; col++) {
            int sel = row;
            for (int i = row; i < eqCnt; i++) {
                if (mat[i][col] > mat[sel][col] + EPS || mat[i][col] < mat[sel][col] - EPS) {
                    if (mat[i][col] < 0 ? -mat[i][col] > (mat[sel][col] < 0 ? -mat[sel][col] : mat[sel][col])
                                        : mat[i][col] > (mat[sel][col] < 0 ? -mat[sel][col] : mat[sel][col]))
                        sel = i;
                }
            }
            double best = mat[sel][col];
            if (best < 0) best = -best;
            if (best < EPS) continue;

            if (sel != row) {
                for (int j = col; j <= varCnt; j++) {
                    double tmp = mat[sel][j];
                    mat[sel][j] = mat[row][j];
                    mat[row][j] = tmp;
                }
            }

            where[col] = row;
            double div = mat[row][col];
            for (int j = col; j <= varCnt; j++) mat[row][j] /= div;

            for (int i = 0; i < eqCnt; i++) {
                if (i == row) continue;
                double factor = mat[i][col];
                if (factor > -EPS && factor < EPS) continue;
                for (int j = col; j <= varCnt; j++) {
                    mat[i][j] -= factor * mat[row][j];
                }
            }
            row++;
        }

        int ok = 1;
        for (int i = 0; i < eqCnt; i++) {
            double all0 = 1.0;
            for (int j = 0; j < varCnt; j++) {
                double v = mat[i][j];
                if (v < 0) v = -v;
                if (v >= EPS) {
                    all0 = 0.0;
                    break;
                }
            }
            double b = mat[i][varCnt];
            if (b < 0) b = -b;
            if (all0 > 0.5 && b >= EPS) {
                ok = 0;
                break;
            }
        }

        int unique = ok;
        if (ok) {
            for (int i = 0; i < varCnt; i++) {
                if (where[i] == -1) {
                    unique = 0;
                    break;
                }
            }
        }

        if (!firstCase) printf("\n");
        firstCase = 0;

        if (!unique) {
            printf("NO\n");
            continue;
        }

        double ans[70];
        for (int i = 0; i < varCnt; i++) ans[i] = 0.0;
        for (int i = 0; i < varCnt; i++) {
            ans[i] = mat[where[i]][varCnt];
        }

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                if (j) printf(" ");
                if (a[i][j].type) {
                    long long v = (long long)(ans[unknownId[i][j]] + (ans[unknownId[i][j]] >= 0 ? 0.5 : -0.5));
                    printf("%lld", v);
                } else {
                    long long v = (long long)(a[i][j].val + (a[i][j].val >= 0 ? 0.5 : -0.5));
                    printf("%lld", v);
                }
            }
            printf("\n");
        }
    }

    return 0;
}

