public class Main {
    static int[][] table;
    static int h, w;
    static boolean[][] known;
    static boolean inf, impossible;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        boolean first = true;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split(" ");
            h = Integer.parseInt(parts[0]);
            w = Integer.parseInt(parts[1]);
            if (h == 0 && w == 0) break;
            if (!first) System.out.println();
            first = false;
            table = new int[h][w];
            known = new boolean[h][w];
            inf = false;
            impossible = false;

            for (int i = 0; i < h; i++) {
                line = br.readLine().trim();
                parts = line.split(" ");
                for (int j = 0; j < w; j++) {
                    if (parts[j].equals("?")) {
                        table[i][j] = 0;
                        known[i][j] = false;
                    } else {
                        table[i][j] = Integer.parseInt(parts[j]);
                        known[i][j] = true;
                    }
                }
            }

            // Try to fill known values by deduction
            boolean changed = true;
            while (changed) {
                changed = false;
                // rows
                for (int i = 0; i < h - 1; i++) {
                    int unknownCol = -1;
                    int sum = 0;
                    int unknowns = 0;
                    for (int j = 0; j < w; j++) {
                        if (known[i][j]) {
                            sum += table[i][j];
                        } else {
                            unknownCol = j;
                            unknowns++;
                        }
                    }
                    if (unknowns == 1 && known[h-1][i]) {
                        int val = table[h-1][i] - sum;
                        if (!known[i][unknownCol]) {
                            known[i][unknownCol] = true;
                            table[i][unknownCol] = val;
                            changed = true;
                        } else if (table[i][unknownCol] != val) {
                            impossible = true;
                        }
                    }
                }
                // columns
                for (int j = 0; j < w - 1; j++) {
                    int unknownRow = -1;
                    int sum = 0;
                    int unknowns = 0;
                    for (int i = 0; i < h; i++) {
                        if (known[i][j]) {
                            sum += table[i][j];
                        } else {
                            unknownRow = i;
                            unknowns++;
                        }
                    }
                    if (unknowns == 1 && known[h-1][j]) {
                        int val = table[h-1][j] - sum;
                        if (!known[unknownRow][j]) {
                            known[unknownRow][j] = true;
                            table[unknownRow][j] = val;
                            changed = true;
                        } else if (table[unknownRow][j] != val) {
                            impossible = true;
                        }
                    }
                }
                // total row and column
                int totalSum = 0;
                boolean totalKnown = true;
                for (int j = 0; j < w - 1; j++) {
                    if (known[h-1][j]) totalSum += table[h-1][j];
                    else totalKnown = false;
                }
                if (totalKnown && known[h-1][w-1]) {
                    int val = table[h-1][w-1] - totalSum;
                    if (!known[h-1][w-1]) {
                        known[h-1][w-1] = true;
                        table[h-1][w-1] = val;
                        changed = true;
                    } else if (table[h-1][w-1] != val) {
                        impossible = true;
                    }
                }
            }

            if (impossible) {
                System.out.println("NO");
                continue;
            }

            // Check if any unknowns remain
            boolean hasUnknown = false;
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    if (!known[i][j]) hasUnknown = true;
                }
            }

            if (!hasUnknown) {
                for (int i = 0; i < h; i++) {
                    for (int j = 0; j < w; j++) {
                        System.out.print(table[i][j] + (j == w-1 ? "" : " "));
                    }
                    System.out.println();
                }
            } else {
                System.out.println("NO");
            }
        }
    }
}

