import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;
        int tc = Integer.parseInt(first);

        StringBuilder out = new StringBuilder();

        for (int caseNum = 0; caseNum < tc; caseNum++) {
            int n = fs.nextInt();
            int m = fs.nextInt();

            // table size: n rows + total row, m cols + total col
            String[][] raw = new String[n + 1][m + 1];
            boolean[][] unknown = new boolean[n + 1][m + 1];
            long[] value = new long[(n + 1) * (m + 1)];

            int vars = 0;
            long[] knownVal = new long[(n + 1) * (m + 1)];
            Arrays.fill(knownVal, Long.MIN_VALUE);

            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= m; j++) {
                    String s = fs.next();
                    raw[i][j] = s;
                    int id = i * (m + 1) + j;
                    if (s.equals("?")) {
                        unknown[i][j] = true;
                        value[id] = vars++;
                    } else {
                        knownVal[id] = Long.parseLong(s);
                    }
                }
            }

            // Equations:
            // For each row i<n: sum a[i][0..m-1] - a[i][m] = 0
            // For each col j<m: sum a[0..n-1][j] - a[n][j] = 0
            // Last grand total equation is redundant, so not added.
            int eqCount = n + m;

            BitSet[] coef = new BitSet[eqCount];
            long[] rhs = new long[eqCount];
            for (int e = 0; e < eqCount; e++) coef[e] = new BitSet(vars);

            int eq = 0;
            for (int i = 0; i < n; i++) {
                long b = 0;
                for (int j = 0; j < m; j++) {
                    int id = i * (m + 1) + j;
                    if (unknown[i][j]) coef[eq].flip((int) value[id]);
                    else b -= knownVal[id];
                }
                int id = i * (m + 1) + m;
                if (unknown[i][m]) coef[eq].flip((int) value[id]);
                else b += knownVal[id];
                rhs[eq] = b;
                eq++;
            }

            for (int j = 0; j < m; j++) {
                long b = 0;
                for (int i = 0; i < n; i++) {
                    int id = i * (m + 1) + j;
                    if (unknown[i][j]) coef[eq].flip((int) value[id]);
                    else b -= knownVal[id];
                }
                int id = n * (m + 1) + j;
                if (unknown[n][j]) coef[eq].flip((int) value[id]);
                else b += knownVal[id];
                rhs[eq] = b;
                eq++;
            }

            // Solve over integers. Since coefficients are only 0/1 in these equations,
            // and structure is a bipartite incidence system, uniqueness can be tested by rank.
            // We use Gaussian elimination over doubles? No, integer-safe rational elimination.
            // But there is a simpler graph interpretation:
            // unknown cells are edges between row-equations and column-equations,
            // row totals / column totals are also edges to only one equation.
            // However totals cells can appear in exactly one equation.
            //
            // We can solve by repeated propagation:
            // if an equation has exactly one unknown, determine it.
            // If after exhaustion any unknown remains, infinitely many solutions.
            // If contradiction occurs, no solution.

            int totalCells = (n + 1) * (m + 1);
            boolean[] isUnknown = new boolean[totalCells];
            long[] ans = new long[totalCells];
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= m; j++) {
                    int id = i * (m + 1) + j;
                    isUnknown[id] = unknown[i][j];
                    if (!isUnknown[id]) ans[id] = knownVal[id];
                }
            }

            ArrayList<Integer>[] eqVars = new ArrayList[eqCount];
            ArrayList<Integer>[] varEqs = new ArrayList[totalCells];
            for (int i = 0; i < totalCells; i++) varEqs[i] = new ArrayList<>();
            long[] sumKnown = new long[eqCount];
            int[] deg = new int[eqCount];

            eq = 0;
            for (int i = 0; i < n; i++) {
                eqVars[eq] = new ArrayList<>();
                for (int j = 0; j < m; j++) {
                    int id = i * (m + 1) + j;
                    if (isUnknown[id]) {
                        eqVars[eq].add(id);
                        varEqs[id].add(eq);
                        deg[eq]++;
                    } else sumKnown[eq] += ans[id];
                }
                int id = i * (m + 1) + m;
                if (isUnknown[id]) {
                    eqVars[eq].add(id);
                    varEqs[id].add(eq);
                    deg[eq]++;
                } else sumKnown[eq] -= ans[id];
                eq++;
            }

            for (int j = 0; j < m; j++) {
                eqVars[eq] = new ArrayList<>();
                for (int i = 0; i < n; i++) {
                    int id = i * (m + 1) + j;
                    if (isUnknown[id]) {
                        eqVars[eq].add(id);
                        varEqs[id].add(eq);
                        deg[eq]++;
                    } else sumKnown[eq] += ans[id];
                }
                int id = n * (m + 1) + j;
                if (isUnknown[id]) {
                    eqVars[eq].add(id);
                    varEqs[id].add(eq);
                    deg[eq]++;
                } else sumKnown[eq] -= ans[id];
                eq++;
            }

            boolean[] solved = new boolean[totalCells];
            ArrayDeque<Integer> q = new ArrayDeque<>();
            for (int e = 0; e < eqCount; e++) if (deg[e] == 1) q.add(e);

            boolean bad = false;
            int solvedCount = 0;
            while (!q.isEmpty()) {
                int e = q.poll();
                if (deg[e] != 1) continue;

                int target = -1;
                for (int id : eqVars[e]) {
                    if (isUnknown[id] && !solved[id]) {
                        target = id;
                        break;
                    }
                }
                if (target == -1) continue;

                // Equation form:
                // row eq: sum(items) - total = 0
                // col eq: sum(items) - total = 0
                // sumKnown[e] currently includes known contributions with signs (+items, -total)
                // so unknown target must satisfy contribution = -sumKnown[e]
                // target coefficient is +1 for non-total cells in that equation, -1 for total cell.
                int ti = target / (m + 1);
                int tj = target % (m + 1);

                long coeff;
                if (e < n) { // row equation
                    coeff = (tj == m) ? -1 : 1;
                } else { // col equation
                    coeff = (ti == n) ? -1 : 1;
                }

                long val;
                if (coeff == 1) val = -sumKnown[e];
                else val = sumKnown[e];

                ans[target] = val;
                solved[target] = true;
                solvedCount++;

                for (int ee : varEqs[target]) {
                    if (deg[ee] <= 0) continue;

                    int ci = target / (m + 1);
                    int cj = target % (m + 1);
                    long c;
                    if (ee < n) c = (cj == m) ? -1 : 1;
                    else c = (ci == n) ? -1 : 1;

                    sumKnown[ee] += c * val;
                    deg[ee]--;
                    if (deg[ee] == 0) {
                        if (sumKnown[ee] != 0) {
                            bad = true;
                            break;
                        }
                    } else if (deg[ee] == 1) {
                        q.add(ee);
                    }
                }
                if (bad) break;
            }

            if (!bad) {
                for (int e = 0; e < eqCount; e++) {
                    if (deg[e] == 0 && sumKnown[e] != 0) {
                        bad = true;
                        break;
                    }
                }
            }

            int unknownCount = 0;
            for (int i = 0; i < totalCells; i++) if (isUnknown[i]) unknownCount++;

            if (caseNum > 0) out.append('\n');

            if (bad || solvedCount != unknownCount) {
                out.append("NO\n");
            } else {
                for (int i = 0; i <= n; i++) {
                    for (int j = 0; j <= m; j++) {
                        if (j > 0) out.append(' ');
                        int id = i * (m + 1) + j;
                        out.append(ans[id]);
                    }
                    out.append('\n');
                }
            }
        }

        System.out.print(out.toString());
    }
}

