#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

static const long long INF64 = (1LL << 60);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    bool firstOutput = true;

    while (true) {
        int n, m;
        if (!(cin >> n >> m)) return 0;
        if (n == 0 && m == 0) break;

        vector<vector<string>> s(n + 1, vector<string>(m + 1));
        vector<vector<long long>> a(n + 1, vector<long long>(m + 1, 0));
        vector<vector<bool>> unknown(n + 1, vector<bool>(m + 1, false));

        for (int i = 0; i <= n; ++i) {
            for (int j = 0; j <= m; ++j) {
                cin >> s[i][j];
                if (s[i][j] == "?") {
                    unknown[i][j] = true;
                } else {
                    a[i][j] = stoll(s[i][j]);
                }
            }
        }

        int vars = 0;
        vector<vector<int>> id(n + 1, vector<int>(m + 1, -1));
        vector<pair<int,int>> pos;
        for (int i = 0; i <= n; ++i) {
            for (int j = 0; j <= m; ++j) {
                if (unknown[i][j]) {
                    id[i][j] = vars++;
                    pos.push_back({i, j});
                }
            }
        }

        // Build linear system Ax = b over reals/integers.
        // Row constraints: sum row items = row total
        // For i in [0..n-1], sum_{j=0..m-1} cell(i,j) - cell(i,m) = 0
        // Column constraints: sum col items = col total
        // For j in [0..m-1], sum_{i=0..n-1} cell(i,j) - cell(n,j) = 0
        // Grand total consistency is implied.
        int eqs = n + m;
        vector<vector<long double>> mat(eqs, vector<long double>(vars + 1, 0));

        int r = 0;
        for (int i = 0; i < n; ++i, ++r) {
            long long rhs = 0;
            for (int j = 0; j < m; ++j) {
                if (unknown[i][j]) mat[r][id[i][j]] += 1;
                else rhs -= a[i][j];
            }
            if (unknown[i][m]) mat[r][id[i][m]] -= 1;
            else rhs += a[i][m];
            mat[r][vars] = rhs;
        }

        for (int j = 0; j < m; ++j, ++r) {
            long long rhs = 0;
            for (int i = 0; i < n; ++i) {
                if (unknown[i][j]) mat[r][id[i][j]] += 1;
                else rhs -= a[i][j];
            }
            if (unknown[n][j]) mat[r][id[n][j]] -= 1;
            else rhs += a[n][j];
            mat[r][vars] = rhs;
        }

        // Gaussian elimination to determine uniqueness and values.
        const long double EPS = 1e-12L;
        int row = 0;
        vector<int> where(vars, -1);

        for (int col = 0; col < vars && row < eqs; ++col) {
            int sel = row;
            for (int i = row; i < eqs; ++i) {
                if (fabsl(mat[i][col]) > fabsl(mat[sel][col])) sel = i;
            }
            if (fabsl(mat[sel][col]) < EPS) continue;
            swap(mat[sel], mat[row]);
            where[col] = row;

            long double div = mat[row][col];
            for (int j = col; j <= vars; ++j) mat[row][j] /= div;

            for (int i = 0; i < eqs; ++i) {
                if (i == row) continue;
                long double factor = mat[i][col];
                if (fabsl(factor) < EPS) continue;
                for (int j = col; j <= vars; ++j) {
                    mat[i][j] -= factor * mat[row][j];
                }
            }
            ++row;
        }

        bool inconsistent = false;
        for (int i = 0; i < eqs; ++i) {
            bool allZero = true;
            for (int j = 0; j < vars; ++j) {
                if (fabsl(mat[i][j]) > EPS) {
                    allZero = false;
                    break;
                }
            }
            if (allZero && fabsl(mat[i][vars]) > EPS) {
                inconsistent = true;
                break;
            }
        }

        bool unique = !inconsistent;
        if (unique) {
            for (int j = 0; j < vars; ++j) {
                if (where[j] == -1) {
                    unique = false;
                    break;
                }
            }
        }

        if (!firstOutput) cout << "\n";
        firstOutput = false;

        if (!unique) {
            cout << "NO\n";
            continue;
        }

        vector<long long> ans(vars, 0);
        bool okInteger = true;
        for (int j = 0; j < vars; ++j) {
            long double v = mat[where[j]][vars];
            long long iv = llround(v);
            if (fabsl(v - (long double)iv) > 1e-8L) {
                okInteger = false;
                break;
            }
            ans[j] = iv;
        }

        if (!okInteger) {
            cout << "NO\n";
            continue;
        }

        for (int k = 0; k < vars; ++k) {
            auto [i, j] = pos[k];
            a[i][j] = ans[k];
        }

        // Final verification
        bool ok = true;
        for (int i = 0; i < n; ++i) {
            long long sum = 0;
            for (int j = 0; j < m; ++j) sum += a[i][j];
            if (sum != a[i][m]) ok = false;
        }
        for (int j = 0; j < m; ++j) {
            long long sum = 0;
            for (int i = 0; i < n; ++i) sum += a[i][j];
            if (sum != a[n][j]) ok = false;
        }
        long long total1 = 0, total2 = 0;
        for (int j = 0; j < m; ++j) total1 += a[n][j];
        for (int i = 0; i < n; ++i) total2 += a[i][m];
        if (a[n][m] != total1 || a[n][m] != total2) ok = false;

        if (!ok) {
            cout << "NO\n";
            continue;
        }

        for (int i = 0; i <= n; ++i) {
            for (int j = 0; j <= m; ++j) {
                if (j) cout << ' ';
                cout << a[i][j];
            }
            cout << "\n";
        }
    }

    return 0;
}

