import sys

def solve_dataset(r, c, lines):
    # Parse table, remember positions of '?'
    a = []
    qpos = []
    for i in range(r):
        row = []
        for j, tok in enumerate(lines[i].split()):
            if tok == '?':
                row.append(None)
                qpos.append((i, j))
            else:
                row.append(int(tok))
        a.append(row)

    # Build linear system over unknown cells only.
    # Variables: one per '?'
    idx = {pos: k for k, pos in enumerate(qpos)}
    m = len(qpos)

    equations = []
    rhs = []

    # Row equations: sum of first c-1 cells equals last cell
    for i in range(r - 1):
        coeff = [0] * m
        const = 0
        for j in range(c - 1):
            if a[i][j] is None:
                coeff[idx[(i, j)]] += 1
            else:
                const += a[i][j]
        if a[i][c - 1] is None:
            coeff[idx[(i, c - 1)]] -= 1
        else:
            const -= a[i][c - 1]
        equations.append(coeff)
        rhs.append(-const)

    # Column equations: sum of first r-1 cells equals last cell
    for j in range(c - 1):
        coeff = [0] * m
        const = 0
        for i in range(r - 1):
            if a[i][j] is None:
                coeff[idx[(i, j)]] += 1
            else:
                const += a[i][j]
        if a[r - 1][j] is None:
            coeff[idx[(r - 1, j)]] -= 1
        else:
            const -= a[r - 1][j]
        equations.append(coeff)
        rhs.append(-const)

    # Grand total equation
    coeff = [0] * m
    const = 0
    for i in range(r - 1):
        for j in range(c - 1):
            if a[i][j] is None:
                coeff[idx[(i, j)]] += 1
            else:
                const += a[i][j]
    if a[r - 1][c - 1] is None:
        coeff[idx[(r - 1, c - 1)]] -= 1
    else:
        const -= a[r - 1][c - 1]
    equations.append(coeff)
    rhs.append(-const)

    # Gaussian elimination over rationals enough here because coefficients are integers
    # and we only accept unique integer solution in the end.
    # Use Fraction-free style with floats avoided by using rational pairs? Simpler:
    # use Python's Fraction.
    from fractions import Fraction

    mat = [[Fraction(x) for x in row] + [Fraction(b)] for row, b in zip(equations, rhs)]
    n_eq = len(mat)
    n_var = m

    rank = 0
    where = [-1] * n_var

    for col in range(n_var):
        sel = -1
        for row in range(rank, n_eq):
            if mat[row][col] != 0:
                sel = row
                break
        if sel == -1:
            continue
        mat[rank], mat[sel] = mat[sel], mat[rank]
        pivot = mat[rank][col]
        for j in range(col, n_var + 1):
            mat[rank][j] /= pivot
        for row in range(n_eq):
            if row != rank and mat[row][col] != 0:
                factor = mat[row][col]
                for j in range(col, n_var + 1):
                    mat[row][j] -= factor * mat[rank][j]
        where[col] = rank
        rank += 1

    # Check consistency
    for row in range(n_eq):
        all_zero = True
        for col in range(n_var):
            if mat[row][col] != 0:
                all_zero = False
                break
        if all_zero and mat[row][n_var] != 0:
            return None  # no solution

    # Unique?
    if rank < n_var:
        return None  # infinitely many solutions

    sol = [Fraction(0) for _ in range(n_var)]
    for i in range(n_var):
        sol[i] = mat[where[i]][n_var]
        if sol[i].denominator != 1:
            return None
        sol[i] = sol[i].numerator

    return [str(sol[idx[pos]]) for pos in qpos]


def main():
    data = sys.stdin.read().strip().splitlines()
    out = []
    p = 0
    first = True

    while p < len(data):
        if not data[p].strip():
            p += 1
            continue
        r, c = map(int, data[p].split())
        p += 1
        if r == 0 and c == 0:
            break
        lines = data[p:p + r]
        p += r

        ans = solve_dataset(r, c, lines)
